import {
  For, Show, createContext, createEffect, createMemo, createSignal, lazy, useContext,
} from 'solid-js';
import type { JSX } from 'solid-js';
import { endpoint, fetchNodeShape } from '../../stores/corpus.js';
import { isOpen, setOpen } from '../../stores/open-state.js';
import { text, view } from '../../stores/view.js';
import { Chevron } from '../shared/chip.jsx';
import { Kv } from '../shared/header.jsx';
import type { KvRow } from '../shared/header.jsx';
import { headerControls } from '../shared/header-selection.js';
import { LongText } from '../shared/long-text.jsx';
import { safeHref } from '../shared/safe-link.js';
import {
  coversNode, directParent, coreFieldsFor, typeLabelForNode, shapeHasContent, foldShape,
} from './form-model.js';
import { restoreLater } from './recovery-queue.js';
import type { FormRow, FormShape } from './form-model.js';
import './form.css';

const FormRowEdit = lazy(() => import('./form-edit.jsx'));

const LANG_TOKEN = 40;
const langToken = (t: string): boolean => String(t).length >= LANG_TOKEN && !/\s/.test(t);

export function FormValueView(props: {
  v: FormRow['values'][number]; mono?: boolean;
}): JSX.Element {
  const v = () => props.v;
  const cls = () => [props.mono ? 'mono' : '', langToken(v().text) ? 'hash' : '']
    .filter(Boolean).join(' ');
  const href = () => safeHref(v().kind === 'link' ? v().text : v().iri);
  return (
    <Show
      when={v().kind === 'link' || (v().kind === 'label' && v().external)
        ? href()
        : null}
      fallback={(
        <Show when={cls()} fallback={<span>{v().text}</span>}>
          <span class={cls()}>{v().text}</span>
        </Show>
      )}
    >
      {(h) => <a href={h()} target="_blank" rel="noopener">{v().text}</a>}
    </Show>
  );
}

export function FormValues(props: { row: FormRow }): JSX.Element {
  const mono = () => !!props.row.pattern;
  const covered = () => props.row.values.some((v) => v.iri && coversNode(v.iri));
  const chain = useContext(NodeChain);
  const rowSpot = () => `#${props.row.path || props.row.label}${props.row.inverse ? '^' : ''}`;
  return (
    <Show when={!covered()} fallback={(
      <div class="knoop-vouwen">
        <NodeChain.Provider value={[...chain, rowSpot()]}>
          <For each={props.row.values}>{(v) => (
            <NodeFold iri={v.iri}><FormValueView v={v} mono={mono()} /></NodeFold>
          )}</For>
        </NodeChain.Provider>
      </div>
    )}
    >
    <Show
      when={props.row.values.length > 1}
      fallback={(
        <span>
          <For each={props.row.values}>{(v) => <FormValueView v={v} mono={mono()} />}</For>
        </span>
      )}
    >
      <span class="c-chips">
        <For each={props.row.values}>{(v, i) => (
          <>
            <Show when={i() > 0}><span class="c-ruimte"> </span></Show>
            <span class="c-slot right"><FormValueView v={v} mono={mono()} /></span>
          </>
        )}</For>
      </span>
    </Show>
    </Show>
  );
}

// The open key of a fold is the chain of ancestors plus the spot, so the same node
// in two places keeps two open states.
export const NodeChain = createContext<readonly string[]>([]);

export function NodeFold(props: { iri: string | null | undefined; children: JSX.Element }): JSX.Element {
  const chain = useContext(NodeChain);
  const iri = () => props.iri || '';
  const covers = () => !!iri() && !chain.includes(iri()) && coversNode(iri());
  const openKey = () => 'vorm:' + [...chain, iri()].join('>');
  return (
    <Show when={covers()} fallback={props.children}>
      <NodeFoldOpen iri={iri()} openKey={openKey()} chain={chain}>{props.children}</NodeFoldOpen>
    </Show>
  );
}

export function RowFold(props: {
  iri: string | null | undefined;
  header: (chevron: JSX.Element | null) => JSX.Element;
}): JSX.Element {
  const chain = useContext(NodeChain);
  const iri = () => props.iri || '';
  const covers = () => !!iri() && !chain.includes(iri()) && coversNode(iri());
  const openKey = () => 'vorm:' + [...chain, iri()].join('>');
  return (
    <Show when={covers()} fallback={props.header(null)}>
      <NodeFoldOpen iri={iri()} openKey={openKey()} chain={chain} rowHeader={props.header} />
    </Show>
  );
}

function NodeFoldOpen(props: {
  iri: string; openKey: string; chain: readonly string[]; children?: JSX.Element;
  rowHeader?: (chevron: JSX.Element | null) => JSX.Element;
}): JSX.Element {
  const restored = isOpen(props.openKey);
  const [open, setOpenState] = createSignal(restored);
  const [built, setBuilt] = createSignal(!restored);
  let el: HTMLDetailsElement | undefined;
  if (restored) restoreLater({ el: () => el, build: () => setBuilt(true) });
  const [busy, setBusy] = createSignal(false);
  const [hopped, setHopped] = createSignal(false);
  createEffect(() => {
    if (!open() || !endpoint()) return;
    setBusy(true);
    void fetchNodeShape(props.iri).finally(() => { setBusy(false); setHopped(true); });
  });
  const identifier = () => coreFieldsFor(props.iri).map((v) => v.text).join(' ');
  const type = () => typeLabelForNode(props.iri);
  const shape = createMemo(() => foldShape(props.iri, directParent(props.chain)));
  const contentKnown = () => !endpoint() || hopped();
  const foldable = createMemo(() => {
    if (!contentKnown()) return true;
    const m = shape();
    return m === null || shapeHasContent(m);
  });
  const headerContent = () => (
    <>
      <Show when={type()}>
        {(t) => (
          <>
            <span class="method knoop-type" title={t().afgekort ? t().vol : undefined}>
              {t().text}
            </span>
            <span class="c-ruimte"> </span>
          </>
        )}
      </Show>
      <span class="knoop-regel">{props.children}</span>
      <Show when={identifier()}>
        <span class="c-ruimte"> </span>
        <span class="chip type knoop-kenmerk">{identifier()}</span>
      </Show>
    </>
  );
  return (
    <Show
      when={foldable()}
      fallback={(

        <Show when={props.rowHeader} fallback={(
          <div class="knoop-fold knoop-fold-plat" data-knoop={props.iri}>
            <div class="knoop-summary knoop-kop-plat">{headerContent()}</div>
          </div>
        )}
        >{(k) => k()(null)}</Show>
      )}
    >
    {(_open) => (
    <details
      ref={el}
      class={props.rowHeader ? 'c-fold rij-fold' : 'c-fold knoop-fold'}
      data-open-key={props.openKey}
      data-knoop={props.iri}
      open={open()}
      onToggle={(e) => {
        const nowOpen = e.currentTarget.open;
        if (nowOpen === open()) return;
        setBuilt(true);
        setOpenState(nowOpen);
        setOpen(props.openKey, nowOpen);
      }}
    >
      <summary
        class={props.rowHeader ? 'vl-summary rij-summary' : 'vl-summary knoop-summary'}
        data-art={props.rowHeader ? props.iri : undefined}
        {...headerControls()}
      >
        <Show when={props.rowHeader} fallback={<>{headerContent()}<Chevron small /></>}>
          {(k) => k()(<Chevron small />)}
        </Show>
      </summary>
      <div class={props.rowHeader ? 'c-fold-body rij-fold-body' : 'c-fold-body knoop-fold-body'}>
        <Show when={open()}>

          <Show when={busy()}>
            <p class="muted knoop-laden">{text('shape.loading')}</p>
          </Show>
          <Show when={built()}>
            <Show when={shape()}>
              {(m) => (
                <NodeChain.Provider value={[...props.chain, props.iri]}>

                  <Form m={m()} term={props.iri} header={false} />
                </NodeChain.Provider>
              )}
            </Show>
          </Show>
        </Show>
      </div>
    </details>
    )}
    </Show>
  );
}

const asParagraph = (row: FormRow): string => row.values.map((v) => v.text).join(', ');

const ungroupedReference = (row: FormRow): boolean => row.kind === 'row'
  && row.values.some((v) => v.iri && coversNode(v.iri));

function RowValue(props: {
  row: FormRow; term?: string | null; multiline?: boolean;
}): JSX.Element {
  const plain = () => (props.multiline
    ? <LongText text={asParagraph(props.row)} />
    : <FormValues row={props.row} />);
  return (
    <Show when={view.editMode && props.term} fallback={plain()}>
      <FormRowEdit
        row={props.row}
        term={props.term as string}
        multiline={props.multiline}
      />
    </Show>
  );
}

export function Form(props: {
  m: FormShape;
  header?: boolean;
  term?: string | null;
}): JSX.Element {
  const header = () => props.header !== false;
  const groups = () => props.m.blocks.filter((b) => b.kind === 'group');
  const rows = (rows: FormRow[]): KvRow[] => rows.map((r) => ({
    label: r.label,
    desc: r.description,
    value: <RowValue row={r} term={props.term} />,
  }));
  return (
    <div class="artifact-form">
      <Show when={header()}>
        <div class="artifact-title">
          <span>{props.m.title}</span>

          <For each={props.m.keyInfo}>{(it) => (
            <>
              <span class="c-ruimte"> </span>
              <span class="chip type">{it.text}</span>
            </>
          )}</For>
        </div>
      </Show>
      <Show when={props.m.description}>
        {(d) => <p class="muted"><LongText text={d()} /></p>}
      </Show>
      <For each={props.m.blocks}>{(b) => (
        <Show
          when={b.kind === 'group' ? (b as { rows: FormRow[] }) : null}
          fallback={(
            <Show
              when={ungroupedReference(b as FormRow)}
              fallback={(
                <p class="artifact-note muted">
                  <span class="artifact-note-label">{b.label + ': '}</span>
                  <RowValue row={b as FormRow} term={props.term} multiline />
                </p>
              )}
            >
              <div class="artifact-note muted">
                <span class="artifact-note-label">{b.label + ': '}</span>
                <RowValue row={b as FormRow} term={props.term} />
              </div>
            </Show>
          )}
        >
          {(g) => (
            <>
              <Show when={groups().length > 1 && b.label}>
                <div class="form-group-label">{b.label}</div>
              </Show>
              <Kv rows={rows(g().rows)} />
            </>
          )}
        </Show>
      )}</For>
    </div>
  );
}
