import type { JSX } from 'solid-js';
import { rememberOpenGesture } from './scroll-sync.js';

export function selectionWithin(node: Node): boolean {
  const sel = (typeof window !== 'undefined' && window.getSelection)
    ? window.getSelection() : null;
  if (!sel || !String(sel).trim()) return false;
  const anchor = sel.anchorNode;
  const el = anchor && anchor.nodeType === 1 ? anchor : (anchor && anchor.parentNode);
  return !!(el && node.contains && node.contains(el));
}

export interface HeaderControls {
  onMouseDown: JSX.EventHandler<HTMLElement, MouseEvent>;
  onClick: JSX.EventHandler<HTMLElement, MouseEvent>;
}

// `selectable.test.ts` scans the source: every <summary> in src/ must spread
// these, or that header silently toggles while the reader selects text.
export function headerControls(): HeaderControls {
  let openOnMouseDown: boolean | null = null;
  return {
    onMouseDown(e) {
      const sum = e.currentTarget;
      if ((e.detail || 1) <= 1) {
        const fold = sum.parentElement as HTMLDetailsElement | null;
        openOnMouseDown = fold ? !!fold.open : null;
      }
    },
    onClick(e) {
      const sum = e.currentTarget;
      if (!selectionWithin(sum)) {

        rememberOpenGesture(sum.parentElement);
        return;
      }
      e.preventDefault();
      if ((e.detail || 1) > 1 && openOnMouseDown !== null && sum.parentElement) {
        (sum.parentElement as HTMLDetailsElement).open = openOnMouseDown;
      }
    },
  };
}
