import {
  builtinShapes, countCovered, coveredClasses, dropBacklinks, formModel, isCovered, keyInfoFor,
  readShapes, shapeForNode, shapeForNodeIndexed, shapeIndex, typeLabelFor,
} from '../../model/forms.js';
import { getLang } from '../../model/i18n.js';
import { coveredCount, graph, graphVersion } from '../../stores/corpus.js';
import type { Graph } from '../../model-boundary.js';

export interface FormValue {
  kind: 'text' | 'link' | 'label';
  text: string;
  iri: string | null;
  external?: boolean;
}

export interface FormRow {
  kind: 'row';
  label: string;
  description: string | null;
  path: string | null;
  inverse: boolean;
  pattern: string | null;
  viewer: string | null;
  values: FormValue[];
  order: number | null;
}

export interface FormGroup {
  kind: 'group';
  label: string;
  rows: FormRow[];
  order: number | null;
}

export type FormBlock = FormGroup | FormRow;

export interface FormShape {
  shape: string;
  title: string;
  keyInfo: FormValue[];
  description: string | null;
  blocks: FormBlock[];
}

interface Shape { iri: string; targetClass: string; store: unknown; properties: unknown[] }

const readShapesFn = readShapes as unknown as (store: Graph) => Shape[];
const builtin = builtinShapes as unknown as (ttl?: string[]) => Shape[];
const shapeOfNode = shapeForNode as unknown as (
  store: Graph, iri: string, shapes: Shape[], fallbacks?: Shape[]) => Shape | null;
const buildShape = formModel as unknown as (store: Graph, iri: string, shape: Shape) => FormShape;
const coveredClassSet = coveredClasses as unknown as (
  store: Graph, shapes: Shape[]) => Set<string>;
const nodeCovered = isCovered as unknown as (
  store: Graph, iri: string, classes: Set<string>) => boolean;
const countCoveredNodes = countCovered as unknown as (store: Graph, classes: Set<string>) => number;
type ShapeIndex = Map<string, { shape: Shape }>;
const buildIndex = shapeIndex as unknown as (
  store: Graph, shapes: Shape[], fallbacks?: Shape[]) => ShapeIndex;
const shapeFromIndex = shapeForNodeIndexed as unknown as (
  store: Graph, iri: string, index: ShapeIndex) => Shape | null;
const keyFields = keyInfoFor as unknown as (
  store: Graph, iri: string, shape: Shape | null) => FormValue[];
const typeLabelOf = typeLabelFor as unknown as (
  store: Graph, shape: Shape | null) => TypeLabel | null;

export interface TypeLabel { text: string; vol: string; afgekort: boolean }

// All caches key on graph identity plus graph version; the fold cache also on language.
let cache: { g: Graph; v: number; shapes: Shape[] } | null = null;

export function forgetShapes(): void {
  cache = null; coverage = null; index = null; folds = null;
}

function sourceShapes(g: Graph): Shape[] {
  const v = graphVersion();
  if (!cache || cache.g !== g || cache.v !== v) cache = { g, v, shapes: readShapesFn(g) };
  return cache.shapes;
}

function bundledShapes(): Shape[] {
  return builtin();
}

function artifactShapeDef(): Shape | null {
  return bundledShapes()[0] || null;
}

function shapeOf(iri: string | null | undefined, fallback: Shape | null): FormShape | null {
  void graphVersion();
  const g = graph() as Graph | null;
  if (!g || !iri) return null;
  const shape = shapeOfNode(g, iri, sourceShapes(g), bundledShapes())
    || fallback;
  if (!shape) return null;
  return buildShape(g, iri, shape);
}

export function formShapeForNode(iri: string | null | undefined): FormShape | null {
  return shapeOf(iri, null);
}

let coverage: { g: Graph; v: number; classes: Set<string> } | null = null;

function coverageFor(g: Graph): Set<string> {
  const v = graphVersion();
  if (coverage && coverage.g === g && coverage.v === v) return coverage.classes;
  const classes = coveredClassSet(g, [...sourceShapes(g), ...bundledShapes()]);
  coverage = { g, v, classes };
  return classes;
}

export function coversNode(iri: string | null | undefined): boolean {
  const g = graph() as Graph | null;
  if (!g || !iri) return false;
  return nodeCovered(g, iri, coverageFor(g));
}

let index: { g: Graph; v: number; ix: ShapeIndex } | null = null;

function indexFor(g: Graph): ShapeIndex {
  const v = graphVersion();
  if (index && index.g === g && index.v === v) return index.ix;
  const ix = buildIndex(g, sourceShapes(g), bundledShapes());
  index = { g, v, ix };
  return ix;
}

export function coreFieldsFor(iri: string | null | undefined): FormValue[] {
  const g = graph() as Graph | null;
  if (!g || !iri) return [];
  return keyFields(g, iri, shapeFromIndex(g, iri, indexFor(g)));
}

export const withoutParentRef = dropBacklinks as unknown as (
  m: FormShape, parent: string | null) => FormShape;

export function foldShape(
  iri: string | null | undefined, parent: string | null,
): FormShape | null {
  void graphVersion();
  const g = graph() as Graph | null;
  if (!g || !iri) return null;
  const key = iri + '\u0000' + (parent || '');
  const c = foldCache(g);
  const hit = c.get(key);
  if (hit !== undefined) return hit;
  const shape = shapeFromIndex(g, iri, indexFor(g));
  const raw = shape ? buildShape(g, iri, shape) : formShapeForNode(iri);
  const m = raw ? withoutParentRef(raw, parent) : null;
  c.set(key, m);
  return m;
}

let folds: { g: Graph; v: number; lang: string; m: Map<string, FormShape | null> } | null = null;

function foldCache(g: Graph): Map<string, FormShape | null> {
  const v = graphVersion();
  const lang = getLang() as string;
  if (folds && folds.g === g && folds.v === v && folds.lang === lang) return folds.m;
  folds = { g, v, lang, m: new Map() };
  return folds.m;
}

export function shapeHasContent(m: FormShape | null): boolean {
  return !!m && (m.blocks.length > 0 || !!m.description);
}

export function directParent(chain: readonly string[]): string | null {
  return chain.length >= 2 ? chain[chain.length - 2] : null;
}

export function typeLabelForNode(iri: string | null | undefined): TypeLabel | null {
  const g = graph() as Graph | null;
  if (!g || !iri) return null;
  return typeLabelOf(g, shapeFromIndex(g, iri, indexFor(g)));
}

export function coveredNodes(): number {
  const fromEndpoint = coveredCount();
  if (fromEndpoint !== null) return fromEndpoint;
  const g = graph() as Graph | null;
  if (!g) return 0;
  return countCoveredNodes(g, coverageFor(g));
}

export function artifactShape(iri: string | null | undefined): FormShape | null {
  return shapeOf(iri, artifactShapeDef());
}
